cssCode:
#container { display: flex; justify-content: center; align-items: center; background: #0a0a0f; perspective: 1000px; }
.sonic-ring {
  width: 250px; height: 250px; position: relative;
  transform-style: preserve-3d; transition: transform 0.1s ease-out;
}
.circle-layer {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  border-radius: 50%; border: 2px solid transparent;
}
.c1 { border-top: 2px solid #00ffcc; border-bottom: 2px solid #00ffcc; transform: translateZ(30px) scale(1.1); animation: spin1 4s linear infinite; }
.c2 { border-left: 2px solid #ff007f; border-right: 2px solid #ff007f; transform: translateZ(0px) scale(1.0); animation: spin2 5s linear infinite; }
.c3 { border-top: 2px dashed #00d2ff; transform: translateZ(-30px) scale(0.9); animation: spin3 6s linear infinite; }

.core-text {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%) translateZ(50px);
  color: white; font-family: sans-serif; font-size: 24px; font-weight: 900;
  text-shadow: 0 0 20px #fff; letter-spacing: 5px;
}

@keyframes spin1 { 100% { transform: translateZ(30px) scale(1.1) rotateZ(360deg) rotateX(20deg); } }
@keyframes spin2 { 100% { transform: translateZ(0px) scale(1.0) rotateZ(-360deg) rotateY(20deg); } }
@keyframes spin3 { 100% { transform: translateZ(-30px) scale(0.9) rotateZ(360deg) rotateX(-20deg); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;justify-content:center;align-items:center;background:#0a0a0f;perspective:1000px;';

c.innerHTML = `
  <div class="sonic-ring" id="sRing">
    <div class="circle-layer c1"></div>
    <div class="circle-layer c2"></div>
    <div class="circle-layer c3"></div>
    <div class="core-text">ZYNK</div>
  </div>
`;

const sRing = document.getElementById('sRing');

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  const x = (e.clientX - rect.left - rect.width/2) * 0.15;
  const y = (e.clientY - rect.top - rect.height/2) * -0.15;

  // આખી સિસ્ટમને 3D માં ફેરવવા
  sRing.style.transform = `rotateX(${y}deg) rotateY(${x}deg)`;
});

c.addEventListener('pointerleave', () => {
  sRing.style.transform = `rotateX(0deg) rotateY(0deg)`;
});
